"use strict";(self.webpackChunkwoocommerce_booking_and_reservation_doc=self.webpackChunkwoocommerce_booking_and_reservation_doc||[]).push([[491],{4194(t,e,o){o.r(e),o.d(e,{_pageData:()=>r,default:()=>a});var s=o(641);const r=JSON.parse('{"path":"/booking-and-reservation/persons.html","title":"People and Guests","lang":"en-US","frontmatter":{"title":"People and Guests","description":"Ask customers for a guest count, cap it, choose between private and shared capacity, and create person types such as Adult and Child with their own prices and limits."},"git":{},"filePathRelative":"booking-and-reservation/persons.md"}'),n={name:"persons.md"},a=(0,o(6262).A)(n,[["render",function(t,e,o,r,n,a){const d=(0,s.g2)("RouteLink");return(0,s.uX)(),(0,s.CE)("div",null,[e[4]||(e[4]=(0,s.Fv)('<h1 id="people-and-guests" tabindex="-1"><a class="header-anchor" href="#people-and-guests"><span>People and Guests</span></a></h1><p>The <strong>Persons</strong> tab decides how many people a booking is for, whether one booking takes the whole product or shares it with others, and whether different kinds of guest cost different amounts.</p><p><img src="/woocommerce-booking-and-reservation/images/booking-and-reservation/product-people-settings.png" alt="The People settings for a product"></p><p>The tab opens with the product&#39;s person settings panel, then the people and person-type cards beneath it.</p><p><img src="/woocommerce-booking-and-reservation/images/booking-and-reservation/product-persons.png" alt="The Persons tab and its settings panel"></p><h2 id="people-allowed-for-this-product" tabindex="-1"><a class="header-anchor" href="#people-allowed-for-this-product"><span>People allowed for this product</span></a></h2><p>The first card holds the decisions that matter most.</p><table><thead><tr><th>Setting</th><th>Options</th><th>What it means</th></tr></thead><tbody><tr><td><strong>Ask customer for guest count</strong></td><td><em>Yes, show guest selector</em> / <em>No, every booking counts as 1</em></td><td>Whether the guest field appears at all</td></tr><tr><td><strong>Guest field label</strong></td><td>Free text, default <strong>Guests</strong></td><td>Rename it to <em>Attendees</em>, <em>Passengers</em>, <em>Players</em>…</td></tr><tr><td><strong>Maximum people per booking</strong></td><td>A number</td><td>The cap. A customer who exceeds it is refused</td></tr><tr><td><strong>Booking capacity style</strong></td><td><em>Private booking</em> / <em>Shared capacity</em></td><td>See below</td></tr><tr><td><strong>Total capacity at the same time</strong></td><td>A number, only editable in shared mode</td><td>How many people the product holds at once</td></tr></tbody></table><p>Click <strong>Save people settings</strong>. You get <em>&quot;People settings saved for this product&quot;</em>.</p><h3 id="private-booking-versus-shared-capacity" tabindex="-1"><a class="header-anchor" href="#private-booking-versus-shared-capacity"><span>Private booking versus shared capacity</span></a></h3><p>This is the single most important choice on the tab.</p><table><thead><tr><th></th><th><strong>Private booking</strong></th><th><strong>Shared capacity</strong></th></tr></thead><tbody><tr><td>What happens</td><td>One booking blocks the whole window</td><td>Bookings keep being accepted until the capacity is full</td></tr><tr><td>Good for</td><td>Hotel rooms, vehicle hire, venue hire, a one-to-one appointment</td><td>Tours, classes, workshops, group sessions</td></tr><tr><td>The customer sees</td><td>The window disappears once anyone books it</td><td>The window stays open until the seats run out</td></tr></tbody></table><div class="hint-container important"><p class="hint-container-title">Important</p><p><strong>Private booking</strong> is the safe default. Switching a live product to shared capacity means several customers can suddenly book the same slot — make sure that is what you want before you save.</p></div><h2 id="person-types" tabindex="-1"><a class="header-anchor" href="#person-types"><span>Person types</span></a></h2><p>The second card lets you define the kinds of guest a booking can contain, each with its own price and limits.</p><p><img src="/woocommerce-booking-and-reservation/images/booking-and-reservation/product-person-types.png" alt="Person types"></p><p>Click <strong>Add person type</strong> and fill:</p><table><thead><tr><th>Field</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Internal type name</strong></td><td>A short key you use in rules, e.g. <code>adult</code></td></tr><tr><td><strong>Customer label</strong></td><td>What the customer sees, e.g. <em>Adult</em> or <em>Child (under 12)</em></td></tr><tr><td><strong>Price per person</strong></td><td>Added for each person of this type. <code>0</code> for none</td></tr><tr><td><strong>Minimum quantity</strong></td><td>The fewest of this type a booking may contain — <code>1</code> makes it compulsory</td></tr><tr><td><strong>Maximum quantity</strong></td><td>The most allowed</td></tr><tr><td><strong>Description</strong></td><td>Optional explanation</td></tr><tr><td><strong>Sort order</strong></td><td>Lower numbers appear first</td></tr></tbody></table><p>On the storefront the types appear as a <strong>Person types</strong> group with a quantity box each:</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">Person types</span>\n<span class="line">  Adult              [ 1 ]   Quantity for this person type.</span>\n<span class="line">  Child (under 12)   [ 0 ]   Quantity for this person type.</span>\n<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">Tips</p><p>Set <strong>Minimum quantity</strong> to <code>1</code> on Adult and <code>0</code> on Child. That way a booking always has at least one adult but children are genuinely optional.</p></div><p>When person types are in use, the total across all types becomes the booking&#39;s guest count — so it must still respect <strong>Maximum people per booking</strong>.</p><h2 id="person-based-price-adjustments" tabindex="-1"><a class="header-anchor" href="#person-based-price-adjustments"><span>Person-based price adjustments</span></a></h2><p>The third card prices person types over time or in more complex ways.</p><table><thead><tr><th>Field</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Person type key/name</strong></td><td>The internal type name, e.g. <code>Adult</code></td></tr><tr><td><strong>Person type amount</strong></td><td>The figure to apply</td></tr><tr><td><strong>Person type mode</strong></td><td><em>Add amount per person</em> or <em>Multiply price</em></td></tr><tr><td><strong>Valid from</strong> / <strong>Valid until</strong></td><td>Optional date window</td></tr><tr><td><strong>Priority</strong>, <strong>Status</strong>, <strong>Internal Note</strong></td><td>As for any rule</td></tr></tbody></table><p>For a simple, permanent per-person price, use <strong>Price per person</strong> on the person type itself. Use an adjustment when it changes seasonally or only applies for part of the year.</p><h2 id="store-wide-person-defaults" tabindex="-1"><a class="header-anchor" href="#store-wide-person-defaults"><span>Store-wide person defaults</span></a></h2><p>Set in <strong>Global Settings → Products → Global Persons</strong>. A product uses these until you save an override.</p><table><thead><tr><th>Section</th><th>Setting</th><th>Default</th></tr></thead><tbody><tr><td>Module Settings</td><td>Enable Person/Guest Fields</td><td>Enabled</td></tr><tr><td>Module Settings</td><td>Frontend People Label</td><td>Guests</td></tr><tr><td>Module Settings</td><td>Show Person Type Quantities</td><td>Enabled</td></tr><tr><td>Adult</td><td>Enable Adult Type</td><td>Disabled</td></tr><tr><td>Adult</td><td>Minimum Adult Age</td><td>18</td></tr><tr><td>Adult</td><td>Adult Price Multiplier</td><td>1</td></tr><tr><td>Child</td><td>Enable Child Type</td><td>Disabled</td></tr><tr><td>Child</td><td>Maximum Child Age</td><td>12</td></tr><tr><td>Child</td><td>Child Discount (%)</td><td>0</td></tr><tr><td>Group Types</td><td>Enable Group Types</td><td>Enabled</td></tr><tr><td>Group Types</td><td>Allow Custom Group Type</td><td>Enabled</td></tr><tr><td>Group Types</td><td>Max Group Types</td><td>10</td></tr><tr><td>Capacity Rules</td><td>Enforce Person Capacity</td><td>Enabled</td></tr><tr><td>Capacity Rules</td><td>Default Max Persons</td><td>20</td></tr><tr><td>Capacity Rules</td><td>Allow Waitlist</td><td>Disabled</td></tr></tbody></table><div class="hint-container note"><p class="hint-container-title">Note</p><p>The <strong>Adult</strong> and <strong>Child</strong> sections are convenience settings — an age threshold, a multiplier and a discount. The person types you create on the product are what actually appear on the booking form.</p></div><h2 id="what-happens-if-a-customer-asks-for-too-many-people" tabindex="-1"><a class="header-anchor" href="#what-happens-if-a-customer-asks-for-too-many-people"><span>What happens if a customer asks for too many people</span></a></h2><p>The booking is refused at add-to-cart with:</p><blockquote><p>This product allows up to 4 people per booking.</p></blockquote><p>Raise <strong>Maximum people per booking</strong> if the limit is wrong, or leave it and let the customer split the booking.</p><h2 id="worked-examples" tabindex="-1"><a class="header-anchor" href="#worked-examples"><span>Worked examples</span></a></h2><p><strong>A hotel room for up to four guests</strong></p><ul><li>Ask for guest count: <strong>Yes</strong></li><li>Guest field label: <strong>Guests</strong></li><li>Maximum people per booking: <code>4</code></li><li>Booking capacity style: <strong>Private booking</strong></li></ul><p><strong>A walking tour with 20 places, adults and children priced differently</strong></p><ul><li>Booking capacity style: <strong>Shared capacity</strong></li><li>Total capacity at the same time: <code>20</code></li><li>Person type <em>Adult</em>, price <code>1200</code>, min <code>1</code>, max <code>10</code></li><li>Person type <em>Child</em>, price <code>600</code>, min <code>0</code>, max <code>10</code></li></ul><p><strong>A one-to-one consultation</strong></p><ul><li>Ask for guest count: <strong>No, every booking counts as 1</strong></li><li>Booking capacity style: <strong>Private booking</strong></li></ul><h2 id="checking-your-work" tabindex="-1"><a class="header-anchor" href="#checking-your-work"><span>Checking your work</span></a></h2><ol><li>Open the product on your storefront.</li><li>Confirm the guest field uses your label and the hint reads <em>&quot;Up to N people can join this booking.&quot;</em></li><li>Confirm your person types appear with the right labels and starting quantities.</li><li>Try to book more people than the maximum — you should see the refusal message above.</li><li>For shared capacity, book once and confirm the slot is still bookable; keep booking until it fills.</li></ol><h2 id="next-step" tabindex="-1"><a class="header-anchor" href="#next-step"><span>Next step</span></a></h2>',44)),(0,s.Lk)("ul",null,[(0,s.Lk)("li",null,[(0,s.bF)(d,{to:"/booking-and-reservation/services-and-extras.html"},{default:(0,s.k6)(()=>[...e[0]||(e[0]=[(0,s.eW)("Services, Extras and Fees",-1)])]),_:1}),e[1]||(e[1]=(0,s.eW)(" — charge for what the guests add on.",-1))]),(0,s.Lk)("li",null,[(0,s.bF)(d,{to:"/booking-and-reservation/pricing.html"},{default:(0,s.k6)(()=>[...e[2]||(e[2]=[(0,s.eW)("Pricing",-1)])]),_:1}),e[3]||(e[3]=(0,s.eW)(" — the rest of the pricing engine.",-1))])])])}]])}}]);